def backtrack(current_num, partitions, n, m):
    if current_num > n:
        return True

    for i in range(m):
        possible = True
        # Check 1: x+y = current_num
        for x in partitions[i]:
            for y in partitions[i]:
                if x + y == current_num:
                    possible = False
                    break
            if not possible: break
        if not possible: continue

        # Check 2: x+current_num = y
        for x in partitions[i]:
            if x + current_num in partitions[i]:
                possible = False
                break
        if not possible: continue

        # Check 3: current_num+current_num = y
        if current_num + current_num in partitions[i]:
            possible = False
        if not possible: continue

        partitions[i].append(current_num)
        if backtrack(current_num + 1, partitions, n, m):
            return True
        partitions[i].pop()

    return False

